new PluginReexport([
  {
    entries: ['models'],
    template({ files }) {
      return files
        .map(({ name, fileName }) => {
          const exportType = fileName.endsWith('.types.ts') ? ' type' : '';

          return `export${exportType} * from './${name}';`;
        })
        .join('\n');
    },
  },
]),
